CREATE TABLE IF NOT EXISTS public.agenda_disponibilidad_profesores (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), profesor_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, dia_semana SMALLINT NOT NULL CHECK (dia_semana BETWEEN 0 AND 4), hora_inicio TIME NOT NULL DEFAULT '15:00:00', hora_fin TIME NOT NULL DEFAULT '19:00:00', activo BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (profesor_id, dia_semana), CHECK (hora_inicio < hora_fin));
ALTER TABLE public.agenda_disponibilidad_profesores ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "agenda_disponibilidad_select_authenticated" ON public.agenda_disponibilidad_profesores;
CREATE POLICY "agenda_disponibilidad_select_authenticated" ON public.agenda_disponibilidad_profesores FOR SELECT TO authenticated USING (TRUE);
DROP POLICY IF EXISTS "agenda_disponibilidad_admin_manage" ON public.agenda_disponibilidad_profesores;
CREATE POLICY "agenda_disponibilidad_admin_manage" ON public.agenda_disponibilidad_profesores FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
DROP POLICY IF EXISTS "agenda_disponibilidad_soporte_own_manage" ON public.agenda_disponibilidad_profesores;
CREATE POLICY "agenda_disponibilidad_soporte_own_manage" ON public.agenda_disponibilidad_profesores FOR ALL TO authenticated USING (profesor_id = auth.uid() AND public.has_role(auth.uid(), 'soporte'::public.app_role)) WITH CHECK (profesor_id = auth.uid() AND public.has_role(auth.uid(), 'soporte'::public.app_role));
INSERT INTO public.agenda_disponibilidad_profesores (profesor_id, dia_semana, hora_inicio, hora_fin, activo) SELECT ur.user_id, d.dia, '15:00', '19:00', TRUE FROM public.user_roles ur CROSS JOIN (VALUES (0),(1),(2),(3),(4)) AS d(dia) WHERE ur.role IN ('admin'::public.app_role, 'soporte'::public.app_role) ON CONFLICT (profesor_id, dia_semana) DO NOTHING;
UPDATE public.agenda_disponibilidad_profesores a SET activo = FALSE, updated_at = now() FROM public.profiles p WHERE p.id = a.profesor_id AND lower(coalesce(p.nombre_completo, '')) LIKE '%erick%' AND a.dia_semana = 1;
CREATE OR REPLACE FUNCTION public.agenda_slot_disponible(_profesor_id UUID, _fecha DATE, _hora_inicio TIME) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXTRACT(ISODOW FROM _fecha)::INT BETWEEN 1 AND 5 AND _hora_inicio >= '15:00'::time AND _hora_inicio < '19:00'::time AND EXISTS (SELECT 1 FROM public.agenda_disponibilidad_profesores a WHERE a.profesor_id = _profesor_id AND a.dia_semana = EXTRACT(ISODOW FROM _fecha)::INT - 1 AND a.activo = TRUE AND _hora_inicio >= a.hora_inicio AND _hora_inicio < a.hora_fin); $$;
GRANT EXECUTE ON FUNCTION public.agenda_slot_disponible(UUID, DATE, TIME) TO authenticated;
CREATE OR REPLACE FUNCTION public.validar_sesion_1a1_disponibilidad() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.fecha >= CURRENT_DATE AND NOT public.agenda_slot_disponible(NEW.profesor_id, NEW.fecha, NEW.hora_inicio) THEN RAISE EXCEPTION 'El profesor no está disponible en ese horario. La agenda permite reservas de 15:00 a 19:00 en días habilitados.'; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS validar_sesion_1a1_disponibilidad ON public.sesiones_1a1;
CREATE TRIGGER validar_sesion_1a1_disponibilidad BEFORE INSERT OR UPDATE OF profesor_id, fecha, hora_inicio ON public.sesiones_1a1 FOR EACH ROW EXECUTE FUNCTION public.validar_sesion_1a1_disponibilidad();